#!/usr/bin/env python3
"""
output_guard.py — Stop hook. Checks what Claude SAYS, not only what it does.

The PreToolUse guards inspect tool inputs, so they never see prose. A rule that
only binds inside tool calls does not bind the answer, and the answer is where
the forbidden language kept surviving. This closes that.

Patterns live in ~/.claude/forbidden_patterns.txt, one extended-regex per line.
Adding a rule is an appended line there and never an edit to this file.

On a match: emit {"decision": "block", "reason": ...}. Claude is handed the
reason and must speak again without the offending text. It does not soften, it
does not warn once and pass — it blocks, every time, as instructed.
"""
import sys, json, os, re, time

PATTERNS_FILE = os.path.expanduser("~/.claude/forbidden_patterns.txt")
LOG           = os.path.expanduser("~/.claude/output_guard.log")


def log(msg):
    try:
        with open(LOG, "a") as f:
            f.write(f"[{time.strftime('%Y-%m-%dT%H:%M:%S')}] {msg}\n")
    except Exception:
        pass


def load_patterns():
    pats = []
    try:
        with open(PATTERNS_FILE, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    pats.append(line)
    except Exception as e:
        log(f"patterns unreadable: {e}")
    return pats


def last_assistant_text(transcript_path):
    """The text of the final assistant turn in the transcript."""
    text = []
    try:
        with open(transcript_path, encoding="utf-8") as f:
            rows = [json.loads(l) for l in f if l.strip()]
    except Exception as e:
        log(f"transcript unreadable: {e}")
        return ""
    for row in reversed(rows):
        if row.get("type") != "assistant":
            continue
        content = row.get("message", {}).get("content", [])
        if isinstance(content, str):
            text.append(content)
        else:
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    text.append(block.get("text", ""))
        break
    return "\n".join(text)


def main():
    try:
        payload = json.load(sys.stdin)
    except Exception:
        sys.exit(0)

    # Already blocked once this turn; block again if it still matches. The guard
    # does not get tired.
    transcript = payload.get("transcript_path", "")
    if not transcript:
        sys.exit(0)

    said = last_assistant_text(transcript)
    if not said.strip():
        sys.exit(0)

    hits = []
    for pat in load_patterns():
        try:
            m = re.search(pat, said, re.IGNORECASE)
        except re.error as e:
            log(f"bad pattern {pat!r}: {e}")
            continue
        if m:
            hits.append((pat, m.group(0)))

    if not hits:
        sys.exit(0)

    found = "; ".join(f"{m!r} (rule /{p}/)" for p, m in hits)
    log(f"BLOCKED: {found}")
    reason = (
        "Your message contains forbidden language and was not delivered. Found: "
        + found
        + ". These are standing rules, not preferences: the meekness marker hedges a claim "
        "that stands on its own; a trailer naming a model or tool has no place in the record; "
        "and the Greek axis letters are a foreign gloss on the twelve marks — write the mark "
        "itself or the value name. Say it again without them. Do not comment on the block, do "
        "not apologise for it, and do not explain that a guard fired — just say the thing "
        "properly."
    )
    print(json.dumps({"decision": "block", "reason": reason}))
    sys.exit(0)


main()

